#!/usr/bin/env bash
# Starts a project-local PostgreSQL cluster (no sudo, no Docker needed).
# Data lives in .pgdata/ ; server listens on localhost:${PGPORT:-5433}.
set -euo pipefail
cd "$(dirname "$0")/.."
PGBIN="${PGBIN:-$(ls -d /usr/lib/postgresql/*/bin | sort -V | tail -1)}"
PGPORT="${PGPORT:-5433}"
DATA=".pgdata"
if [ ! -f "$DATA/PG_VERSION" ]; then
  PWFILE=$(mktemp); umask 077
  # superuser password comes from .env (DBFORGE_ADMIN_PASSWORD) – generated by scripts/bootstrap.sh
  grep '^DBFORGE_ADMIN_PASSWORD=' .env | cut -d= -f2- > "$PWFILE"
  "$PGBIN/initdb" -D "$DATA" -U dbforge_admin --auth-local=scram-sha-256 --auth-host=scram-sha-256 --pwfile="$PWFILE" -E UTF8 >/dev/null
  rm -f "$PWFILE"
  cat >> "$DATA/postgresql.conf" <<CONF
port = $PGPORT
listen_addresses = 'localhost'
unix_socket_directories = '$(pwd)/$DATA'
shared_preload_libraries = 'pg_stat_statements'
password_encryption = scram-sha-256
log_min_duration_statement = 500
CONF
fi
if "$PGBIN/pg_ctl" -D "$DATA" status >/dev/null 2>&1; then echo "postgres already running on :$PGPORT"; exit 0; fi
"$PGBIN/pg_ctl" -D "$DATA" -l "$DATA/server.log" -w start >/dev/null
echo "postgres running on localhost:$PGPORT (data: $DATA)"
